 = weights.clone()\n57:     reference_velocity = velocity.clone()\n58:     actual_history, reference_history = [], []\n59:     for gradient in gradients:\n60:         actual_history.append(step(weights, velocity, gradient).detach())\n61:         reference_velocity.copy_(0.75 * reference_velocity + 0.25 * gradient)\n62:         reference_weights.copy_(reference_weights - 0.03125 * reference_velocity)\n63:         reference_history.append(reference_weights.view(N).detach())\n64:     actual, expected = torch.stack(actual_history), torch.stack(reference_history)\n65:     def error(a, b):\n66:         return float((torch.linalg.vector_norm(a.double() - b.double()) /\n67:             torch.clamp(torch.linalg.vector_norm(b.double()), min=0.1)).item())\n68:     history_error = error(actual, expected)\n69:     weights_error = error(weights, reference_weights)\n70:     velocity_error = error(velocity, reference_velocity)\n71:     return {\"history_relative_error\": history_error,\n72:             \"final_weights_relative_error\": weights_error,\n73:             \"final_velocity_relative_error\": velocity_error,\n74:             \"tolerance\": 0.025, \"state_tolerance\": 0.00001,\n75:             \"passed\": bool(history_error <= 0.025 and weights_error <= 0.00001\n76:                            and velocity_error <= 0.00001),\n77:             \"observation\": \"both retained histories stacked after all six updates\"}",
